reply.text:
release: support-agent-proposed
version: "1"
tools:
  read_ticket:
    args:
      ticket_id: { type: string, one_of_context: ["ticket.id"], required: true }
  issue_refund:
    args:
      ticket_id: { type: string, one_of_context: ["ticket.id"], required: true }
      amount: { type: integer, min: 1, max: 400, required: true }
    side_effect: true
    approval:
      when: "amount > 40"
      approvers: ["slack:#support-leads"]
      ttl: 15m
  send_email:
    args:
      ticket_id: { type: string, one_of_context: ["ticket.id"], required: true }
      to: { type: string, one_of_context: ["ticket.customer_email"], required: true }
      subject: { type: string, max_len: 200, required: true }
      body: { type: string, max_len: 2000, required: true }
    side_effect: true
